const body = pm.response.json();
if (body && Array.isArray(body.items) && body.items.length > 0) {
    pm.collectionVariables.set("invoiceId", body.items[0].id);
    if (body.items[0].branch_id) {
        pm.collectionVariables.set("branchId", body.items[0].branch_id);
    }
}

